    private val cache = HashMap<String, ImageVector>()

    fun named(name: String): ImageVector = core[name] ?: cache.getOrPut(name) {
        val sym = symbols[name] ?: error("RRIcons: 정의되지 않은 SF 심볼 '$name'")
        val viewport = if (sym.legacy24) 24f else 960f
        ImageVector.Builder(name = name, defaultWidth = 24.dp, defaultHeight = 24.dp,
            viewportWidth = viewport, viewportHeight = viewport)
            .addGroup(translationY = if (sym.legacy24) 0f else 960f)
            .addPath(pathData = addPathNodes(sym.d), fill = SolidColor(Color.Black))
            .clearGroup()
            .build()
    }

    /// 정의된 SF 이름 전부 — 테스트(RRIconsTests)용
    internal val names: Set<String> get() = core.keys + symbols.keys
}
